CREATE TABLE Discipline ( nom_discipline VARCHAR(40) PRIMARY KEY, mode_pratique  VARCHAR(50) );
CREATE TABLE Equipe ( nom_equipe VARCHAR(50) PRIMARY KEY, nom_discipline VARCHAR(40) NOT NULL, FOREIGN KEY (nom_discipline) REFERENCES Discipline(nom_discipline) );
CREATE TABLE Modele_capteur ( nom_modele VARCHAR(50) PRIMARY KEY, type_capteur VARCHAR(50));
CREATE TABLE Test_physique ( nom_test VARCHAR(50) PRIMARY KEY, unite_resultat DOUBLE);
CREATE TABLE Intervenant ( id_intervenant SMALLINT PRIMARY KEY, fonction VARCHAR(50), nom_intervenant VARCHAR(50), id_intervenant_superviseur SMALLINT NULL, FOREIGN KEY (id_intervenant_superviseur) REFERENCES Intervenant(id_intervenant));
CREATE TABLE Athlete ( numero_licence INT PRIMARY KEY, nom_athlete VARCHAR(50), prenom_athlete VARCHAR(50), date_naissance DATE, sexe VARCHAR(20), taille DECIMAL(6,2), nom_discipline VARCHAR(40) NOT NULL, FOREIGN KEY (nom_discipline) REFERENCES Discipline(nom_discipline) );
CREATE TABLE Capteur ( numero_serie INT PRIMARY KEY, date_etalonnage DATE, nom_modele VARCHAR(50) NOT NULL, FOREIGN KEY (nom_modele) REFERENCES Modele_capteur(nom_modele) );
CREATE TABLE Seance ( code_seance SMALLINT PRIMARY KEY, date_heure_debut DATE, duree DATE, type_seance VARCHAR(50), nom_lieu VARCHAR(50), nom_equipe VARCHAR(50) NULL, FOREIGN KEY (nom_equipe) REFERENCES Equipe(nom_equipe) );
CREATE TABLE Blessure (numero_licence INT, numero_blessure TINYINT, date_blessure DATE, zone_corps VARCHAR(50), gravite VARCHAR(50), date_reprise DATE, code_seance SMALLINT NULL, id_intervenant SMALLINT NOT NULL, PRIMARY KEY (numero_licence, numero_blessure), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence), FOREIGN KEY (code_seance) REFERENCES Seance(code_seance), FOREIGN KEY (id_intervenant) REFERENCES Intervenant(id_intervenant) );
CREATE TABLE Appartenir ( numero_licence INT, nom_equipe VARCHAR(50), poste_occupe VARCHAR(50), date_arrivee DATE, PRIMARY KEY (numero_licence, nom_equipe), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence), FOREIGN KEY (nom_equipe) REFERENCES Equipe(nom_equipe) );
CREATE TABLE Participer ( numero_licence INT, code_seance SMALLINT, distance_totale DECIMAL(8,2), vitesse_max DOUBLE, fc_moyenne DOUBLE, fc_max DOUBLE, charge_entrainement DECIMAL(15,2), PRIMARY KEY (numero_licence, code_seance), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence), FOREIGN KEY (code_seance) REFERENCES Seance(code_seance) );
CREATE TABLE Encadrer ( code_seance SMALLINT, id_intervenant SMALLINT, PRIMARY KEY (code_seance, id_intervenant), FOREIGN KEY (code_seance) REFERENCES Seance(code_seance), FOREIGN KEY (id_intervenant) REFERENCES Intervenant(id_intervenant) );
CREATE TABLE Porter ( numero_licence INT, numero_serie INT, code_seance SMALLINT, PRIMARY KEY (numero_licence, numero_serie, code_seance), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence), FOREIGN KEY (numero_serie) REFERENCES Capteur(numero_serie), FOREIGN KEY (code_seance) REFERENCES Seance(code_seance) );
CREATE TABLE Passer ( numero_licence INT, code_seance SMALLINT, nom_test VARCHAR(50), resultat_test DOUBLE, PRIMARY KEY (numero_licence, code_seance, nom_test), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence), FOREIGN KEY (code_seance) REFERENCES Seance(code_seance), FOREIGN KEY (nom_test) REFERENCES Test_physique(nom_test) );
